import React, { useEffect, useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { getUserRole, logout } from '../Utils/AuthUtils';

export default function StudioSidebar() {
    const location = useLocation();
    const navigate = useNavigate();
    const [expandedMenus, setExpandedMenus] = useState({});
    const [userRole, setUserRole] = useState(null);

    useEffect(() => {
        // Get user role from localStorage
        const role = getUserRole();
        setUserRole(role);
        
        if (window.lucide) {
            window.lucide.createIcons();
        }
    }, [location]);

    const toggleMenu = (menuId) => {
        setExpandedMenus(prev => ({
            ...prev,
            [menuId]: !prev[menuId]
        }));
    };

    const handleLogout = () => {
        logout();
        navigate('/studio/login');
    };

    return (
        <div className="main-nav">
            <div className="d-flex justify-content-between main-logo-box">
                <div className="logo-box">
                    <Link to="/studio" className="logo-dark">
                        <img src="/assets/images/logo-dark.png" className="logo-sm" alt="studio logo sm" />
                        <img src="/assets/images/logo-dark.png" className="logo-lg" alt="studio logo" />
                    </Link>
                    <Link to="/studio" className="logo-light">
                        <img src="/assets/images/logo-light.png" className="logo-sm" alt="studio logo sm" />
                        <img src="/assets/images/logo-light.png" className="logo-lg" alt="studio logo" />
                    </Link>
                </div>
                <button 
                    type="button" 
                    className="btn btn-link d-flex button-sm-hover button-toggle-menu" 
                    aria-label="Show Full Sidebar"
                >
                    <i data-lucide="menu" className="button-sm-hover-icon"></i>
                </button>
            </div>

            <div className="h-100" data-simplebar>
                <ul className="navbar-nav" id="navbar-nav">
                    <li className="menu-item">
                        <Link 
                            to={userRole === 'seller' ? "/studio/seller" : userRole === 'influencer' ? "/studio/influencer" : "/studio"}
                            className={`menu-link ${location.pathname === '/studio' || 
                                (userRole === 'seller' && location.pathname === '/studio/seller') || 
                                (userRole === 'influencer' && location.pathname === '/studio/influencer') ? 'active' : ''}`}
                        >
                            <span className="nav-icon">
                                <i data-lucide="layout-dashboard"></i>
                            </span>
                            <span className="nav-text">Dashboard</span>
                        </Link>
                    </li>

                    {/* Reels Management - Common for both sellers and influencers */}
                    <li className="menu-item">
                        <Link 
                            to="/studio/upload" 
                            className={`menu-link ${location.pathname === '/studio/upload' ? 'active' : ''}`}
                        >
                            <span className="nav-icon">
                                <i data-lucide="upload"></i>
                            </span>
                            <span className="nav-text">Reel Upload</span>
                        </Link>
                    </li>

                    <li className="menu-item">
                        <Link 
                            to="/studio/reels" 
                            className={`menu-link ${location.pathname === '/studio/reels' ? 'active' : ''}`}
                        >
                            <span className="nav-icon">
                                <i data-lucide="film"></i>
                            </span>
                            <span className="nav-text">Reel Manage</span>
                        </Link>
                    </li>

                    <li className="menu-title">Pages</li>

                    <li className="menu-item">
                        <Link 
                            to="/studio/profile" 
                            className={`menu-link ${location.pathname === '/studio/profile' ? 'active' : ''}`}
                        >
                            <span className="nav-icon">
                                <i data-lucide="circle-user"></i>
                            </span>
                            <span className="nav-text">Profile</span>
                        </Link>
                    </li>

                    <li className="menu-item">
                        <a 
                            className="menu-link" 
                            href="#"
                            onClick={(e) => {
                                e.preventDefault();
                                handleLogout();
                            }}
                        >
                            <span className="nav-icon">
                                <i data-lucide="log-out"></i>
                            </span>
                            <span className="nav-text">Logout</span>
                        </a>
                    </li>
                </ul>
            </div>
        </div>
    );
}
